<?php $ci=&get_instance();$b=$production_batch;$can=$ci->permissions('production_batches_edit') && $ci->permissions('items_view');$open=in_array($b->status,['in_production','ready'],true);$status=['planned'=>'Planned','in_production'=>$b->kind==='growing'?'Growing':'Assembling','ready'=>'Ready for review','completed'=>'Completed','cancelled'=>'Cancelled']; ?>
<section class="garden-panel"><a href="<?= base_url('garden/production'); ?>">← Production board</a><div class="garden-panel-heading"><div><span class="garden-kicker"><?= htmlspecialchars($b->batch_code); ?></span><h2><?= htmlspecialchars($b->output_name); ?></h2><p><?= htmlspecialchars($b->warehouse_name); ?> · <?= htmlspecialchars($status[$b->status] ?? $b->status); ?></p></div><span class="garden-pill"><?= $b->kind==='growing'?'Growing batch':'Assembly batch'; ?></span></div><p><?= nl2br(htmlspecialchars($b->notes ?? '')); ?></p>
<div class="garden-grid"><div class="garden-card"><small>Planned units</small><h2><?= (int)$b->planned_qty; ?></h2></div><div class="garden-card"><small>Recorded losses</small><h2><?= (int)$b->lost_qty; ?></h2></div><div class="garden-card"><small><?= $b->status==='completed'?'Confirmed saleable units':'Remaining expected units'; ?></small><h2><?= $b->saleable_qty!==null?(int)$b->saleable_qty:(int)$b->planned_qty-(int)$b->lost_qty; ?></h2></div></div>
<p class="garden-muted">Start: <?= htmlspecialchars($b->started_at ?: 'Not started'); ?> · Expected completion: <?= htmlspecialchars($b->expected_date ?: 'Not set'); ?></p></section>
<section class="garden-panel"><div class="garden-panel-heading"><div><span class="garden-kicker">ACTUAL BATCH COST</span><h2>Inputs, care & finishing</h2></div></div><dl class="garden-cost-lines"><?php foreach(['material'=>'Materials issued','labour'=>'Labour allocated','other'=>'Other costs allocated','total'=>'Total batch cost'] as $key=>$label): ?><div><dt><?= $label; ?></dt><dd><?= store_number_format($production_totals[$key]); ?></dd></div><?php endforeach; ?><div><dt><?= $b->status==='completed'?'Actual cost per saleable unit':'Estimated cost per remaining unit'; ?></dt><dd><?= $b->status==='completed' ? ($b->unit_cost!==null?store_number_format($b->unit_cost):'No saleable output') : ($b->status==='planned'?'Not started':(((int)$b->planned_qty-(int)$b->lost_qty)>0?store_number_format($production_totals['total']/((int)$b->planned_qty-(int)$b->lost_qty)):'No remaining units')); ?></dd></div></dl><p class="garden-muted">Labour and other entries allocate costs to this batch; they do not create expenses or payments. Record supplier bills and payments in Finance. This is a batch costing view; the existing catalogue cost and pricing controls govern standard sales profitability.</p></section>
<?php if($can && $b->status==='planned'): ?><section class="garden-panel garden-inspection-spotlight"><h2>Review & issue starting materials</h2><ul><?php foreach(json_decode($b->materials_json,true)?:[] as $line):$name='Material';foreach($production_items as $i)if((int)$i->id===(int)$line['item_id'])$name=$i->item_name.' · '.($i->unit_name ?: 'stock units'); ?><li><?= htmlspecialchars($name); ?> · <?= format_qty($line['quantity']); ?></li><?php endforeach; ?></ul><p>Starting deducts these quantities from <?= htmlspecialchars($b->warehouse_name); ?> and records their current catalogue cost. Finished products are received only at completion.</p><form method="post" action="<?= base_url('garden/production_action'); ?>"><?php $this->load->view('garden/production_action_fields',['production_action'=>'start']); ?><button class="garden-button">Issue materials & start <?= $b->kind==='growing'?'growing':'assembly'; ?></button></form><details><summary class="garden-disclosure-toggle garden-disclosure-danger">Cancel before starting</summary><form method="post" action="<?= base_url('garden/production_action'); ?>"><?php $this->load->view('garden/production_action_fields',['production_action'=>'cancel']); ?><label>Reason<textarea name="note" maxlength="8000" rows="2"></textarea></label><button type="submit" class="garden-button garden-button-danger">Cancel planned batch</button></form></details></section><?php endif; ?>
<?php if($can && $open): ?><section class="garden-panel"><h2>Record what happened</h2><div class="garden-grid"><details class="garden-card"><summary class="garden-disclosure-toggle">+ Additional material</summary><form method="post" action="<?= base_url('garden/production_action'); ?>"><?php $this->load->view('garden/production_action_fields',['production_action'=>'material']); ?><label>Material<select name="item_id" data-garden-select hidden required><option value="">Choose input</option><?php foreach($production_items as $i):if((int)$i->id===(int)$b->product_item_id)continue; ?><option value="<?= (int)$i->id; ?>"><?= htmlspecialchars($i->item_name.' · '.($i->unit_name ?: 'stock units')); ?></option><?php endforeach; ?></select></label><label>Quantity in stock units<input name="quantity" type="number" min="0.01" step="0.01" required></label><label>Reason<textarea name="note" rows="2" maxlength="8000"></textarea></label><button class="garden-button">Issue material</button></form></details>
<?php foreach(['labour'=>'Labour','other'=>'Other costs'] as $kind=>$label): ?><details class="garden-card"><summary class="garden-disclosure-toggle">+ <?= $label; ?></summary><form method="post" action="<?= base_url('garden/production_action'); ?>"><?php $this->load->view('garden/production_action_fields',['production_action'=>$kind]); ?><label>Allocated amount<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Description / bill reference<textarea name="note" rows="2" maxlength="8000" required></textarea></label><button class="garden-button">Allocate cost</button></form></details><?php endforeach; ?>
<details class="garden-card"><summary class="garden-disclosure-toggle">Record growing / assembly losses</summary><form method="post" action="<?= base_url('garden/production_action'); ?>"><?php $this->load->view('garden/production_action_fields',['production_action'=>'loss']); ?><label>Lost units<input name="quantity" type="number" min="1" max="<?= (int)$b->planned_qty-(int)$b->lost_qty; ?>" step="1" required></label><label>What happened?<textarea name="note" id="production-loss-note" maxlength="8000" rows="3" required></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'production-loss-note']); ?><p class="garden-muted">These are unfinished batch losses. Materials already issued remain in the batch cost; finished catalogue stock is not deducted here.</p><button class="garden-button">Record loss</button></form></details></div></section>
<section class="garden-panel"><h2>Confirm finished output</h2><?php if($b->status!=='ready'): ?><form method="post" action="<?= base_url('garden/production_action'); ?>"><?php $this->load->view('garden/production_action_fields',['production_action'=>'ready']); ?><button class="garden-button">Mark ready for review</button></form><?php endif; ?><form method="post" action="<?= base_url('garden/production_action'); ?>"><?php $this->load->view('garden/production_action_fields',['production_action'=>'complete']); ?><p>Reconcile all planned units as saleable output or recorded losses. Completion receives only the saleable output into stock, once.</p><label>Saleable units<input type="number" name="quantity" min="0" max="<?= (int)$b->planned_qty-(int)$b->lost_qty; ?>" step="1" value="<?= (int)$b->planned_qty-(int)$b->lost_qty; ?>" required></label><label>Completion / quality notes<textarea name="note" id="production-complete-note" rows="3" maxlength="8000"></textarea></label><?php $this->load->view('garden/voice_button',['voice_target'=>'production-complete-note']); ?><button class="garden-button">Complete batch & receive output</button></form></section><?php endif; ?>
<section class="garden-panel"><h2>Batch activity & cost history</h2><div class="garden-timeline"><?php foreach($production_entries as $e): ?><article><small><?= htmlspecialchars($e->created_at.' · '.($e->author ?: 'Team member')); ?></small><strong><?= htmlspecialchars(ucfirst($e->kind).($e->item_name?' · '.$e->item_name:'')); ?></strong><p><?= nl2br(htmlspecialchars($e->note ?? '')); ?></p><?php if((float)$e->quantity>0): ?><span><?= format_qty($e->quantity); ?> units </span><?php endif; ?><?php if((float)$e->cost>0): ?><b><?= store_number_format($e->cost); ?></b><?php endif; ?><?php if($e->adjustment_id): ?><small>Stock movement #<?= (int)$e->adjustment_id; ?></small><?php endif; ?></article><?php endforeach; ?><?php if(!$production_entries): ?><p>No materials have been issued yet.</p><?php endif; ?></div></section>
